-- T004 of specs/003-booking/tasks.md: the Phase 2 pass (specs/003-booking/data-model.md §2.2 to
-- §2.5 and §6 item 2; ERD v1.12). Generated by `prisma migrate diff --from-config-datasource
-- --to-schema prisma/schema --script` against a database holding every migration before it, then
-- extended by hand for what the schema language cannot say.
--
-- What it lands: `enrollments.quoted_first_session_local_date`, the first session's local date the
-- checkout showed (R-209); `payments.expires_at`, the order's expiry as created, and
-- `payments.checkout_url_encrypted`, the hosted checkout's address, encrypted (R-DB-8) and reached
-- by the `reencrypt-columns` job (002:T134); the enum `enrollment_event_kind` and the append-only
-- table `enrollment_events` (R-216), whose foreign keys are RESTRICT on update as on delete
-- (002:T135); and `ijazah_fold(text)`, the one fold of Arabic spelling the name search applies to
-- both sides (R-203). No column holds a fold and no index is built on it (PR #109's review M5,
-- analysis C1, R-DB-9). `enrollments` and `payments` held no row when this was written (Phase 1
-- wrote neither), so the two NOT NULL columns are added without a default.

-- CreateEnum
CREATE TYPE "enrollment_event_kind" AS ENUM ('confirmed', 'order_failed', 'cancelled');

-- AlterTable
ALTER TABLE "enrollments" ADD COLUMN     "quoted_first_session_local_date" DATE NOT NULL;

-- AlterTable
ALTER TABLE "payments" ADD COLUMN     "checkout_url_encrypted" BYTEA,
ADD COLUMN     "expires_at" TIMESTAMPTZ(6) NOT NULL;

-- CreateTable
CREATE TABLE "enrollment_events" (
    "id" UUID NOT NULL DEFAULT uuidv7(),
    "enrollment_id" UUID NOT NULL,
    "kind" "enrollment_event_kind" NOT NULL,
    "cancellation_reason" "cancellation_reason",
    "payment_id" UUID,
    "occurred_at" TIMESTAMPTZ(6) NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "enrollment_events_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "enrollment_events_enrollment_id_idx" ON "enrollment_events"("enrollment_id");

-- CreateIndex
CREATE INDEX "enrollment_events_payment_id_idx" ON "enrollment_events"("payment_id");

-- AddForeignKey
ALTER TABLE "enrollment_events" ADD CONSTRAINT "enrollment_events_enrollment_id_fkey" FOREIGN KEY ("enrollment_id") REFERENCES "enrollments"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "enrollment_events" ADD CONSTRAINT "enrollment_events_payment_id_fkey" FOREIGN KEY ("payment_id") REFERENCES "payments"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- Hand-written: what the schema language cannot say.

-- Rule 39: a row says one thing per kind. A cancellation carries its reason and nothing else does;
-- a confirmation and a failed order carry their order and a cancellation does not (FR-375, FR-385).
ALTER TABLE "enrollment_events" ADD CONSTRAINT "enrollment_events_cancellation_reason_check"
    CHECK (("kind" = 'cancelled') = ("cancellation_reason" IS NOT NULL));

ALTER TABLE "enrollment_events" ADD CONSTRAINT "enrollment_events_payment_check"
    CHECK (("kind" IN ('order_failed', 'confirmed')) = ("payment_id" IS NOT NULL));

-- Rule 39: the row records something that happened, so the application role may not rewrite or
-- remove it (rule 21's pattern, `20261007000500_append_only_tables`). The default privileges of
-- `20261007000100_roles_and_privileges` granted UPDATE and DELETE; TRUNCATE was never granted and
-- is restated so this statement says the whole rule.
REVOKE UPDATE, DELETE, TRUNCATE ON "enrollment_events" FROM ijazah_app;

-- R-203: the fold of FR-333, the same on the stored name and on the typed text. Lower case first,
-- then أ, إ and آ to ا; ى and ئ to ي; ؤ to و; ة to ه; then the diacritics (U+064B to U+065F), the
-- superscript alef (U+0670) and the tatweel (U+0640) removed. Called only by the kernel's query
-- (`apps/api/src/platform/db/folded-name.ts`), on both sides of one LIKE.
CREATE FUNCTION "ijazah_fold"(text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    RETURN regexp_replace(
        translate(lower($1), 'أإآىئؤة', 'اااييوه'),
        '[ً-ٰٟـ]', '', 'g');
